import{_ as e,o as p,c as l,a2 as r}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"사회 서사 배치 B012","description":"","frontmatter":{},"headers":[],"relativePath":"world/Story-Batch-B012.md","filePath":"world/Story-Batch-B012.md"}'),h={name:"world/Story-Batch-B012.md"};function i(t,a,o,d,n,u){return p(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="사회-서사-배치-b012" tabindex="-1">사회 서사 배치 B012 <a class="header-anchor" href="#사회-서사-배치-b012" aria-label="Permalink to &quot;사회 서사 배치 B012&quot;">​</a></h1><p>이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.</p><ul><li>원본 앵커: <code>docs/game-logic/World-Narrative-Atlas.md</code></li><li>원본 해시: <code>61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1</code></li></ul><h2 id="인물-k155-·-주리안" tabindex="-1">인물 K155 · 주리안 <a class="header-anchor" href="#인물-k155-·-주리안" aria-label="Permalink to &quot;인물 K155 · 주리안&quot;">​</a></h2><ul><li>연결: house=HP04 theater=XT05 scenarios=XT05-SC2,STORY-B012-K155</li></ul><h3 id="정체성·출신" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>정릉 옛 배관 맨홀 뚜껑을 열고 주리안은 수압 바늘이 한 칸 떨리는 각도부터 야장에 적는다.</p><p>도성기록청 소속 북부 정수 배관 탐사원이며, 구두 소문보다 봉인된 좌표를 믿는다.</p><p>한국 기원으로 종로 생활권에서 자랐고 손끝은 압력계 보호캡을 습관처럼 돌려 잠근다.</p><p>주리안이라는 표시와 식별자 K153은 이후 배치에서 다시 매겨지지 않는다.</p><h3 id="붕괴-전-삶" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 강북 단절 뒤의 우회관을 기록청 원본 지도에 올리는 습관을 만들었다.</p><p>인준이 늦어도 현장 수압이 지도의 주체가 되게 하려는 계산이었다.</p><p>맨홀 안쪽 분필 점은 서라온에게 원판을 돌려주겠다는 표시였고, 그 점이 훗날 빚의 자리가 된다.</p><p>틀린 수압 로그는 태우지 않고 별도 철통에 넣었다.</p><h3 id="가문·기업·공동체" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>도성기록법가(HP04)는 원본 해시 봉인을 의무로 내밀었고, 주리안은 실재 회사 상호를 배관 야장에 올리지 않는 후계 헌장만 인정했다.</p><p>교대 서명이 없는 탐사 명단은 기록고 벽에 붙이지 않았다.</p><p>맨홀 좌표를 사서와 교량 탐사원에게 같은 시각에 보낸 횟수가 공동체 위치의 증거였다.</p><p>단독 해석 방송 요구는 해시 없음을 이유로 무효가 됐다.</p><h3 id="붕괴의-상처" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>붕괴 날 정릉 배관 세 지점의 수압이 한꺼번에 바닥을 쳤다.</p><p>주리안은 맨홀을 잠그고 서라온의 원판이 도착할 때까지 좌표 공개를 보류했다.</p><p>빈 관이 진본 급수선으로 둔갑해 탐사 직위가 위조 지도의 연장이 되는 그림이 가장 무서웠다.</p><p>사이렌이 끊긴 뒤에도 장갑을 벗지 못한 채 LOSS 목록의 마지막 관경을 읽지 못했다.</p><h3 id="생존-전환점" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>현장 좌표를 서라온의 원판에 이관할지, 마길상의 교량 하부 우회 점선을 먼저 봉인할지가 갈렸다.</p><p>원양신탁전구(XT05)의 인도 목록 해시 보관 요청이 야장 위에 겹쳤다.</p><p>원판 이관을 택하면 기록청 해석은 남지만 야간 맨홀 당직이 빠지고, 점선을 우선하면 한쪽 창구가 배관 해석을 독점한다.</p><p>K155-TURN은 그 겹친 쪽지의 순서다.</p><h3 id="현재-지위" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>주리안은 지금도 정릉과 보문 사이 맨홀 점호를 돌며 야장 큐를 맞춘다.</p><p>직위는 혈통이 아니라 면허와 참관 로그로만 유지된다.</p><p>HP04가 전속 국가 소유를 요구해도 거절하고 Cast 프로필의 현황 칸과 야장을 매주 대조한다.</p><p>맨홀 열쇠 한 자루는 기록고, 다른 한 자루는 수문가 참관함이 나눠 쥐고 있다.</p><h3 id="비밀·빚·죄책감" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>별도 철통 속의 날짜 틀린 수압 로그가 비밀이다.</p><p>살린 맨홀 당직 명단과 그 밤 호출하지 못한 견습의 이름 사이에서 죄책감이 자란다.</p><p>전부를 펼치면 도성 북부 신뢰가 한 칸 끊길 수 있어 부분 공개 절차만 남겼다.</p><p>SECRET 칸은 사서와 교량 탐사원의 동시 서명 없이 열리지 않는다.</p><h3 id="관계-공동과거" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>서라온에게 넘긴 현장 좌표는 사제 계약이었고, 마길상과 나눈 교량 하부 우회 점선은 동맹이었다.</p><p>마하린의 한강 북안 폐선 표시와는 같은 강변을 맞추려다 해석이 어긋난 밤이 있다.</p><p>맨홀 앞에서 서로를 끌어 올린 기록과, 좌표를 하루 숨긴 기록이 함께 남았다.</p><p>관계 원장 끝점은 STORY-B012-K153에 이어진다.</p><h3 id="_3막-개인-서사선" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 주리안은 정릉 세 지점 수압 바닥을 다시 마주한다.</p><p>2막에서 HP04 해시 의무와 XT05 인도 목록 요청을 한 야장에서 순서를 매긴다.</p><p>3막에서 좌표 보류의 값을 맨홀 당직 공백으로 치른다.</p><p>서사선 식별자는 STORY-B012-K153으로 고정된다.</p><h3 id="분기-결말" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한쪽 결말에서 주리안은 원판 이관을 택해 공공 지도의 연속을 살린다.</p><p>다른 결말에서 우회 점선 봉인을 택해 개인 야장과 철통을 지킨다.</p><p>도성기록청 슬롯 자체는 어느 갈래에서도 지워지지 않고 분기 표식만 K155-OUT으로 갈라진다.</p><p>개입은 원판 호송 입회 또는 점선 봉인 입회다.</p><h3 id="_3막" tabindex="-1">3막 <a class="header-anchor" href="#_3막" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 정릉 세 지점 수압 바닥에 맨홀을 잠근다</li><li>2막: HP04 해시와 XT05 인도 목록 요청의 순서를 야장에서 매긴다</li><li>3막: 좌표 보류의 값으로 맨홀 당직 공백을 감수한다</li></ul><h3 id="분기-결말-목록" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K155-OUT-A: 원판 이관으로 공공 지도 연속</li><li>K155-OUT-B: 우회 점선 봉인으로 개인 야장 유지</li></ul><h2 id="인물-k180-·-마하린" tabindex="-1">인물 K180 · 마하린 <a class="header-anchor" href="#인물-k180-·-마하린" aria-label="Permalink to &quot;인물 K180 · 마하린&quot;">​</a></h2><ul><li>연결: house=HP02 theater=XT03 scenarios=XT03-SC1,STORY-B012-K180</li></ul><h3 id="정체성·출신-1" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-1" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>한강철교 북단 신호기 그늘에서 마하린은 침목을 망치로 두드려 빈 울림이 나는 칸만 분필로 표시한다.</p><p>용산철도후국 한강 북안 폐선 탐사원이다.</p><p>한국 기원이며 이촌 쪽 강바람으로 교대 시각을 가늠하는 버릇이 있다.</p><p>표시 마하린과 번호 K177은 후국 명부에서 지워지지 않는다.</p><h3 id="붕괴-전-삶-1" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-1" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>그는 폐선 공동을 환적 우회로로 되살리는 쪽을 밀었다.</p><p>야망은 신호기 함에 접어 둔 손바닥만 한 폐선도였다.</p><p>침목 밑에 숨긴 예비 쐐기가 사적 약속의 씨앗이다.</p><p>공식 배차표에 없는 선은 후국회의에 올리지 않았다.</p><h3 id="가문·기업·공동체-1" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-1" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>환승선로문(HP02)은 중립 배차표를 의무 조항으로 내밀었다.</p><p>마하린은 헌장 참관만 받고 실재 상호를 폐선 야장에서 지웠다.</p><p>우회 좌표를 조정관과 배관 탐사원에게 같은 시각에 넘긴 횟수가 공동체의 자리였다.</p><p>원격 독점 배차 요구는 신호기 봉인 앞에서 돌려보냈다.</p><h3 id="붕괴의-상처-1" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-1" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>한강 수위가 급히 빠지던 밤, 북안 폐선 세 칸이 한꺼번에 내려앉았다.</p><p>마하린은 신호기를 잠그고 박태겸의 우회 허가가 오기 전까지 발을 들이지 않았다.</p><p>내려앉은 칸이 공식 환적선으로 둔갑하는 그림이 가장 짙었다.</p><p>물소리가 잦아든 뒤에도 손의 분필을 놓지 못했다.</p><h3 id="생존-전환점-1" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-1" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>박태겸에게 우회 좌표를 먼저 넘길 것인지, 주리안의 북부 배관 점선과 강변을 맞출 것인지가 갈렸다.</p><p>해협삼로전구(XT03)의 환적창 폐쇄 전갈이 신호기 함에 겹쳤다.</p><p>조정관 쪽을 택하면 열차는 움직이되 배관 실측이 하루 밀리고, 강변 맞춤을 택하면 화물 한 편이 선로 밖에서 밤을 샌다.</p><p>K180-TURN은 그 함에 접힌 쪽지다.</p><h3 id="현재-지위-1" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-1" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>마하린은 여전히 이촌 폐선 구간을 걷고 침목 울림을 후국 칠판에 옮긴다.</p><p>직위는 연공이 아니라 당일 실측 서명으로만 유지된다.</p><p>HP02가 키 이관을 요구해도 신호기 손잡이를 넘기지 않는다.</p><p>폐선 출입 권한은 후국회의와 선로문 참관이 나눠 쥐고 있다.</p><h3 id="비밀·빚·죄책감-1" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-1" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>침목 아래 묻은 예비 쐐기 위치가 비밀이다.</p><p>그날 호출하지 않은 야간 선로공의 이름이 빚이다.</p><p>전부를 파내면 북안 보행 금지 구간이 늘어나 부분 공개만 남겼다.</p><p>쐐기는 조정관과 주리안의 동시 입회 없이 뽑히지 않는다.</p><h3 id="관계-공동과거-1" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-1" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>박태겸에게 우회 좌표를 넘기는 일은 동맹 계약이고, 주리안과 강변을 맞추는 일은 같은 밤의 경쟁이기도 했다.</p><p>내려앉은 칸에서 서로를 끌어 올린 기록이 있고, 좌표를 하루 숨긴 기록도 있다.</p><p>관계의 끝점은 STORY-B012-K177로 이어진다.</p><p>폐선 녹 냄새는 편을 가르는 표식이 되지 않는다.</p><h3 id="_3막-개인-서사선-1" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-1" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 마하린은 내려앉은 폐선 칸의 울림을 다시 듣는다.</p><p>2막에서 HP02 배차 의무와 XT03 환적 폐쇄 전갈을 신호기 함에서 맞춘다.</p><p>3막에서 우회 우선의 값을 화물 야박으로 치른다.</p><p>서사선은 STORY-B012-K177이다.</p><h3 id="분기-결말-1" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-1" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>첫째 갈래에서 마하린은 조정관에게 우회 좌표를 넘겨 환적 연속을 살린다.</p><p>둘째 갈래에서 강변 점선 맞춤을 택해 배관 실측과 비밀 쐐기를 지킨다.</p><p>용산철도후국의 중계 슬롯은 유지되고 식별만 K180-OUT으로 갈린다.</p><p>개입은 우회 호위 또는 강변 측량 입회다.</p><h3 id="_3막-1" tabindex="-1">3막 <a class="header-anchor" href="#_3막-1" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 내려앉은 북안 폐선 칸의 울림을 봉인한다</li><li>2막: HP02 배차와 XT03 환적 폐쇄 전갈을 신호기 함에서 맞춘다</li><li>3막: 우회 우선의 값으로 화물 야박을 감수한다</li></ul><h3 id="분기-결말-목록-1" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-1" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K180-OUT-A: 조정관 우회 좌표로 환적 연속</li><li>K180-OUT-B: 강변 점선 맞춤으로 비밀 쐐기 유지</li></ul><h2 id="인물-k205-·-주나경" tabindex="-1">인물 K205 · 주나경 <a class="header-anchor" href="#인물-k205-·-주나경" aria-label="Permalink to &quot;인물 K205 · 주나경&quot;">​</a></h2><ul><li>연결: house=HP01 theater=XT02 scenarios=XT02-SC3,STORY-B012-K205</li></ul><h3 id="정체성·출신-2" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-2" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>동작대교 하류 부잔교에서 주나경은 채수병 마개를 이빨로 물어 잠그기 전에 강물 온도를 손등으로 확인한다.</p><p>노량진남관상회 한강 취수 탐사원이다.</p><p>한국 기원으로 노량진 선창 골목에서 자랐고, 말보다 시료 라벨의 글씨 굵기를 먼저 고친다.</p><p>주나경과 K201은 상회 명부에서 교체되지 않는다.</p><h3 id="붕괴-전-삶-2" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-2" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 제빙 원수의 탁도를 상회 경매 전에 공개하는 쪽을 밀었다.</p><p>야망은 부잔교 난간에 묶어 둔 여분 채수줄이었다.</p><p>서나연의 제빙 칸에 원수를 대겠다는 약속이 그 줄에 매여 있다.</p><p>탁도 숫자를 숨긴 시료는 경매판에 올리지 않았다.</p><h3 id="가문·기업·공동체-2" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-2" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>아리수수문가(HP01)는 수문 키 분할 보관을 의무로 두었다.</p><p>주나경은 후계 헌장 참관만 받고 실재 제품명을 채수 라벨에서 지웠다.</p><p>교량 하부 채수를 마길상과 나눠 적은 횟수가 공동체 증명이었다.</p><p>전속 취수권 요구는 부잔교 봉인 앞에서 거절됐다.</p><h3 id="붕괴의-상처-2" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-2" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>남관 전력이 깜빡이던 새벽, 취수구 세 곳이 동시에 갈수로 드러났다.</p><p>주나경은 부잔교 사다리를 끌어 올리고 서나연의 제빙 원수 요청이 도착할 때까지 병을 열지 않았다.</p><p>빈 병이 정상 원수로 둔갑해 얼음 신용을 떠받치는 장면이 가장 싫었다.</p><p>강바람이 잦아도 라벨 펜을 주머니에서 빼지 못했다.</p><h3 id="생존-전환점-2" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-2" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>제빙 원수 시료를 서나연에게 우선 보낼지, 교량 하부 채수를 마길상과 나눌지가 갈렸다.</p><p>서해곡창전구(XT02)의 노량진 얼음 신용 흔들림 중계가 부잔교 무전에 겹쳤다.</p><p>제빙을 살리면 상회 칸은 버티지만 교량 쪽 우회 점선이 하루 비고, 교량 채수를 나누면 제빙 한 칸의 온도가 올라간다.</p><p>K205-TURN은 그 무전 순서다.</p><h3 id="현재-지위-2" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-2" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>주나경은 지금도 부잔교와 교각 채수구를 오가며 탁도 큐를 상회 칠판에 옮긴다.</p><p>자리는 지분이 아니라 당일 시료 서명으로만 유지된다.</p><p>HP01가 원격 수문 소유를 요구해도 채수줄 매듭을 넘기지 않는다.</p><p>부잔교 출입 열쇠는 상회정과 수문가 참관이 분할한다.</p><h3 id="비밀·빚·죄책감-2" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-2" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>갈수 직전 한 병을 가족 몫으로 빼 둔 메모가 비밀이다.</p><p>살린 제빙 칸과 그 때문에 줄인 이웃 배분 사이에서 죄책감이 자란다.</p><p>전부 공개 대신 부분 라벨 공개만 남겼다.</p><p>메모는 서나연 입회와 탁도 기록의 동시 대조 없이 펼쳐지지 않는다.</p><h3 id="관계-공동과거-2" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-2" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>서나연의 제빙 원수를 현장에서 측량하는 일은 사제 계약이고, 마길상의 교량 하부 채수와 우회 점선은 나눔 계약이다.</p><p>같은 부잔교에서 병을 나눠 살린 새벽이 있고, 라벨을 하루 숨긴 새벽도 있다.</p><p>관계 끝점은 STORY-B012-K201로 이어진다.</p><p>강물 온도는 편을 가르는 증거가 되지 않는다.</p><h3 id="_3막-개인-서사선-2" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-2" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 주나경은 취수구 갈수를 다시 만난다.</p><p>2막에서 HP01 키 분할과 XT02 얼음 신용 중계를 부잔교 무전에서 맞춘다.</p><p>3막에서 시료 우선의 값을 제빙 칸 온도 상승으로 치른다.</p><p>서사선은 STORY-B012-K201이다.</p><h3 id="분기-결말-2" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-2" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한 갈래에서 주나경은 제빙 원수 우선 인도로 상회 신용을 붙든다.</p><p>다른 갈래에서 교량 채수 나눔을 택해 우회 점선과 비밀 메모를 지킨다.</p><p>노량진남관상회 시장 슬롯은 남고 표식만 K205-OUT이다.</p><p>개입은 원수 호송 또는 교각 채수 입회다.</p><h3 id="_3막-2" tabindex="-1">3막 <a class="header-anchor" href="#_3막-2" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 취수구 갈수에 부잔교 사다리를 끌어 올린다</li><li>2막: HP01 키 분할과 XT02 얼음 신용 중계를 무전에서 맞춘다</li><li>3막: 시료 우선의 값으로 제빙 칸 온도 상승을 감수한다</li></ul><h3 id="분기-결말-목록-2" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-2" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K205-OUT-A: 제빙 원수 우선으로 상회 신용 유지</li><li>K205-OUT-B: 교량 채수 나눔으로 비밀 메모 유지</li></ul><h2 id="인물-k230-·-복두모" tabindex="-1">인물 K230 · 복두모 <a class="header-anchor" href="#인물-k230-·-복두모" aria-label="Permalink to &quot;인물 K230 · 복두모&quot;">​</a></h2><ul><li>연결: house=HP09 theater=XT05 scenarios=XT05-SC1,STORY-B012-K230</li></ul><h3 id="정체성·출신-3" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-3" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>상암 송신탑 콘크리트 기슭에서 복두모는 측량줄 눈금이 바람 때문에 흔들리면 숫자를 읽지 않고 다시 고정한다.</p><p>상암송신공사 지도 갱신 탐사원이다.</p><p>한국 기원이며 난지 방수로 표석 이끼로 계절을 헤아린다.</p><p>복두모라는 이름과 K226은 편성회의 명부에서 교체되지 않는다.</p><h3 id="붕괴-전-삶-3" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-3" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 송신 좌표와 보행 실측을 같은 갱신판에 올리는 쪽을 밀었다.</p><p>야망은 탑 하부 공구함에 접어 둔 손때 묻은 격자지였다.</p><p>권미래에게 탑 좌표를 넘기겠다는 약속이 그 격자 모서리에 있다.</p><p>검증 없는 소문은 갱신판에 올리지 않았다.</p><h3 id="가문·기업·공동체-3" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-3" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>데이터신탁가(HP09)는 모델 카드 공개를 의무로 두었다.</p><p>복두모는 헌장 참관만 받고 실재 상호를 격자지에서 지웠다.</p><p>관문 중계 실측을 모국과 나눈 횟수가 공동체 위치였다.</p><p>전속 대역 소유 요구는 탑 기슭 봉인 앞에서 반려됐다.</p><h3 id="붕괴의-상처-3" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-3" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>잔여 대역 추첨이 어그러지던 저녁, 송신탑 세 방위 표지가 한꺼번에 깜빡임을 잃었다.</p><p>복두모는 측량줄을 감고 권미래의 수신 확인이 오기 전까지 갱신판을 내리지 않았다.</p><p>꺼진 표지가 정상 항로로 인쇄되는 일이 가장 무서웠다.</p><p>발전기 소음이 잦아도 격자지를 접지 못했다.</p><h3 id="생존-전환점-3" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-3" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>탑 좌표를 권미래에게 먼저 넘길지, 서북 관문 중계 실측을 모국과 나눌지가 갈렸다.</p><p>원양신탁전구(XT05)의 잔여 대역 공개 추첨 독촉이 공구함에 겹쳤다.</p><p>송신 쪽을 살리면 방송은 이어지되 관문 보행 안내가 하룻밤 비고, 관문 실측을 나누면 추첨 시각이 밀린다.</p><p>K230-TURN은 그 독촉 쪽지의 접힌 순서다.</p><h3 id="현재-지위-3" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-3" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>복두모는 지금도 탑 기슭과 난지 표석을 오가며 격자 큐를 편성회의에 넘긴다.</p><p>자리는 길드 연공이 아니라 당일 실측 해시로만 유지된다.</p><p>HP09가 원격 모델 독점을 요구해도 공구함 키를 넘기지 않는다.</p><p>갱신판 봉인은 검증관 창구와 신탁 참관이 나눈다.</p><h3 id="비밀·빚·죄책감-3" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-3" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>깜빡임이 끊기기 직전 한 방위 숫자를 개인 격자 여백에 옮긴 일이 비밀이다.</p><p>살린 추첨 시각과 그 밤 안내하지 못한 보행 한 줄 사이에서 죄책감이 자란다.</p><p>전부 공개 대신 이중 참관 하의 여백 대조만 남겼다.</p><p>여백은 권미래와 모국의 동시 입회 없이 펼쳐지지 않는다.</p><h3 id="관계-공동과거-3" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-3" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>권미래에게 탑 좌표를 넘기는 일은 계약이고, 모국의 관문 중계와 실측을 나누는 일도 계약이다.</p><p>같은 기슭에서 표지를 다시 밝힌 저녁이 있고, 숫자를 하루 숨긴 저녁도 있다.</p><p>관계 끝점은 STORY-B012-K226으로 이어진다.</p><p>대역 잡음은 편을 가르는 증거가 되지 않는다.</p><h3 id="_3막-개인-서사선-3" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-3" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 복두모는 꺼진 세 방위 표지를 다시 만난다.</p><p>2막에서 HP09 공개 의무와 XT05 추첨 독촉을 공구함에서 맞춘다.</p><p>3막에서 좌표 우선의 값을 관문 안내 공백으로 치른다.</p><p>서사선은 STORY-B012-K226이다.</p><h3 id="분기-결말-3" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-3" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한 갈래에서 복두모는 탑 좌표 우선 인도로 공개 추첨을 살린다.</p><p>다른 갈래에서 관문 실측 나눔을 택해 보행 안내와 여백 비밀을 지킨다.</p><p>상암송신공사 편성 슬롯은 남고 표식만 K230-OUT이다.</p><p>개입은 추첨 입회 또는 관문 실측 호위다.</p><h3 id="_3막-3" tabindex="-1">3막 <a class="header-anchor" href="#_3막-3" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 꺼진 송신탑 세 방위 표지에 측량줄을 감는다</li><li>2막: HP09 공개 의무와 XT05 추첨 독촉을 공구함에서 맞춘다</li><li>3막: 좌표 우선의 값으로 관문 안내 공백을 감수한다</li></ul><h3 id="분기-결말-목록-3" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-3" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K230-OUT-A: 탑 좌표 인도로 공개 추첨 유지</li><li>K230-OUT-B: 관문 실측 나눔으로 여백 비밀 유지</li></ul><h2 id="인물-k256-·-복모" tabindex="-1">인물 K256 · 복모 <a class="header-anchor" href="#인물-k256-·-복모" aria-label="Permalink to &quot;인물 K256 · 복모&quot;">​</a></h2><ul><li>연결: house=HP05 theater=XT01 scenarios=XT01-SC1,STORY-B012-K256</li></ul><h3 id="정체성·출신-4" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-4" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>구기 터널 입구 이정표 아래에서 복모는 분필 가루가 장갑에 묻으면 글자를 다시 쓰고 나서야 발걸음을 옮긴다.</p><p>북산피난연맹 피난로 탐사원이다.</p><p>한국 기원으로 정릉 회랑 쪽에서 자랐고, 큰소리보다 이정표 획의 굵기를 먼저 고친다.</p><p>복모라는 표시와 K251은 연맹 명부에서 재번호되지 않는다.</p><h3 id="붕괴-전-삶-4" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-4" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 숙영 우회로를 연맹 공개 지도에 올리되 매복 지점은 빼는 쪽을 밀었다.</p><p>야망은 이정표 뒷면에 긁어 둔 작은 화살표였다.</p><p>강태산에게 우회로를 보고하겠다는 약속이 그 화살표에 남아 있다.</p><p>확인되지 않은 지름길은 숙영 칠판에 올리지 않았다.</p><h3 id="가문·기업·공동체-4" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-4" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>북산귀환회(HP05)는 가족 재결합 명부를 의무로 두었다.</p><p>복모는 헌장 참관만 받고 실재 상호를 이정표 야장에서 지웠다.</p><p>회랑 안내 표지를 두소와 맞춘 횟수가 공동체 위치였다.</p><p>전속 회랑 소유 요구는 터널 입구 봉인 앞에서 거절됐다.</p><h3 id="붕괴의-상처-4" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-4" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>임진 쪽 귀환 명부가 훼손되던 날, 구기 터널 안 세 갈래 중 하나가 낙석으로 막혔다.</p><p>복모는 이정표를 뒤집고 강태산의 정찰 응답이 오기 전까지 사람들을 들이지 않았다.</p><p>막힌 길이 열린 피난로로 인쇄되는 일이 가장 싫었다.</p><p>돌가루가 가라앉아도 분필을 놓지 못했다.</p><h3 id="생존-전환점-4" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-4" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>우회로를 강태산에게 먼저 보고할지, 두소의 회랑 이정표에 표시를 옮길지가 갈렸다.</p><p>임진관문전구(XT01)의 귀환 명부 재발급 독촉이 장갑 안 쪽지에 겹쳤다.</p><p>정찰 보고를 택하면 산악 반은 움직이되 숙영 한 줄이 멀리 돌아가고, 이정표를 먼저 고치면 명부 창구가 하루 멈춘다.</p><p>K256-TURN은 그 쪽지의 접힌 면이다.</p><h3 id="현재-지위-4" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-4" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>복모는 지금도 구기와 정릉 회랑을 오가며 이정표 큐를 연맹 칠판에 옮긴다.</p><p>자리는 민병 연공이 아니라 당일 보행 서명으로만 유지된다.</p><p>HP05가 명부 독점을 요구해도 분필 상자를 넘기지 않는다.</p><p>터널 출입 권한은 연방회의와 귀환회 참관이 나눈다.</p><h3 id="비밀·빚·죄책감-4" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-4" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>낙석 직전 한 갈래를 가족 숙영용으로 지운 화살표가 비밀이다.</p><p>살린 정찰 반과 그 밤 안내하지 못한 피난 한 줄 사이에서 죄책감이 자란다.</p><p>전부 공개 대신 이중 입회 하의 화살표 대조만 남겼다.</p><p>화살표는 강태산과 두소의 동시 확인 없이 다시 그려지지 않는다.</p><h3 id="관계-공동과거-4" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-4" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>강태산에게 우회로를 보고하는 일은 계약이고, 두소의 회랑 안내 표지와 표시를 맞추는 일도 계약이다.</p><p>같은 터널에서 낙석을 함께 피한 낮이 있고, 화살표를 하루 지운 낮도 있다.</p><p>관계 끝점은 STORY-B012-K251로 이어진다.</p><p>분필 가루는 편을 가르는 증거가 되지 않는다.</p><h3 id="_3막-개인-서사선-4" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-4" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 복모는 막힌 터널 갈래를 다시 만난다.</p><p>2막에서 HP05 명부 의무와 XT01 재발급 독촉을 장갑 쪽지에서 맞춘다.</p><p>3막에서 보고 우선의 값을 숙영 우회 거리로 치른다.</p><p>서사선은 STORY-B012-K251이다.</p><h3 id="분기-결말-4" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-4" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한 갈래에서 복모는 정찰 보고를 택해 산악 반의 연속을 살린다.</p><p>다른 갈래에서 이정표 수정을 택해 숙영 안내와 비밀 화살표를 지킨다.</p><p>북산피난연맹 회랑 슬롯은 남고 표식만 K256-OUT이다.</p><p>개입은 정찰 호위 또는 이정표 입회다.</p><h3 id="_3막-4" tabindex="-1">3막 <a class="header-anchor" href="#_3막-4" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 낙석으로 막힌 구기 터널 갈래에 이정표를 뒤집는다</li><li>2막: HP05 명부와 XT01 재발급 독촉을 장갑 쪽지에서 맞춘다</li><li>3막: 보고 우선의 값으로 숙영 우회 거리를 감수한다</li></ul><h3 id="분기-결말-목록-4" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-4" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K256-OUT-A: 정찰 보고로 산악 반 연속</li><li>K256-OUT-B: 이정표 수정으로 비밀 화살표 유지</li></ul><h2 id="인물-k282-·-복두" tabindex="-1">인물 K282 · 복두 <a class="header-anchor" href="#인물-k282-·-복두" aria-label="Permalink to &quot;인물 K282 · 복두&quot;">​</a></h2><ul><li>연결: house=HC08 theater=XT04 scenarios=XT04-SC2,STORY-B012-K282</li></ul><h3 id="정체성·출신-5" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-5" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>창동 유치선 분기기 손잡이에서 복두는 기름 냄새보다 유간 두께를 먼저 자로 잰다.</p><p>창동차륜방 북부 선로 탐사원이다.</p><p>한국 기원으로 도봉 주거 쉘 쪽에서 자랐고, 구령보다 렌치 클릭 횟수를 믿는다.</p><p>복두라는 표시와 K276은 연공회의 명부에서 지워지지 않는다.</p><h3 id="붕괴-전-삶-5" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-5" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 북문 우회로를 궤도기병 칠판에 올리되 가문 비선은 빼는 쪽을 밀었다.</p><p>야망은 분기기 덮개 안쪽에 긁어 둔 유간 숫자였다.</p><p>권도하에게 우회로를 넘기겠다는 약속이 그 숫자에 붙어 있다.</p><p>계측 없는 지름길은 기병 배차에 올리지 않았다.</p><h3 id="가문·기업·공동체-5" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-5" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>한화에어로스페이스(HC08)은 궤도 경비와 비상 배차 우선을 의무로 내밀었다.</p><p>복두는 헌장 참관만 받고 실재 상호를 유간 야장에서 지웠다.</p><p>북문 거점 칠판에 실측을 옮긴 횟수가 두국과의 공동체 위치였다.</p><p>전속 기지 소유 요구는 분기기 봉인 앞에서 돌려보냈다.</p><h3 id="붕괴의-상처-5" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-5" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>동절 연료 큐가 어그러지던 새벽, 유치선 세 가닥 중 하나가 동결로 붙었다.</p><p>복두는 손잡이를 잠그고 권도하의 기병 응답이 오기 전까지 열차를 들이지 않았다.</p><p>붙은 가닥이 정상 북문선으로 배차되는 일이 가장 짙은 공포였다.</p><p>김이 잦아도 렌치를 손에서 놓지 못했다.</p><h3 id="생존-전환점-5" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-5" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>북문 우회로를 권도하에게 먼저 넘길지, 두국의 거점 칠판에 실측을 옮길지가 갈렸다.</p><p>두만극동전구(XT04)의 동절 연료 큐 분할 독촉이 덮개 안 쪽지에 겹쳤다.</p><p>기병 쪽을 살리면 순찰은 나가되 거점 안내가 한 칸 늦고, 칠판을 먼저 고치면 연료 호송이 한 편 멈춘다.</p><p>K282-TURN은 그 쪽지의 기름 지문이다.</p><h3 id="현재-지위-5" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-5" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>복두는 지금도 유치선과 도봉 북문 침목을 오가며 유간 큐를 차륜방 칠판에 옮긴다.</p><p>자리는 가문 연공이 아니라 당일 계측 서명으로만 유지된다.</p><p>HC08가 원격 배차 독점을 요구해도 손잡이 키를 넘기지 않는다.</p><p>분기기 출입 권한은 연공회의와 방위문 참관이 나눈다.</p><h3 id="비밀·빚·죄책감-5" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-5" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>동결 직전 한 가닥의 유간을 개인 야장 여백에만 남긴 일이 비밀이다.</p><p>살린 기병 반과 그 새벽 안내하지 못한 호송 한 편 사이에서 죄책감이 자란다.</p><p>전부 공개 대신 이중 입회 하의 여백 대조만 남겼다.</p><p>여백은 권도하와 두국의 동시 확인 없이 칠판에 옮겨지지 않는다.</p><h3 id="관계-공동과거-5" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-5" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>권도하에게 북문 우회로를 넘기는 일은 계약이고, 두국의 거점 칠판에 실측을 옮기는 일도 계약이다.</p><p>같은 유치선에서 동결을 함께 깬 새벽이 있고, 유간을 하루 숨긴 새벽도 있다.</p><p>관계 끝점은 STORY-B012-K276으로 이어진다.</p><p>기름 냄새는 편을 가르는 증거가 되지 않는다.</p><h3 id="_3막-개인-서사선-5" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-5" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 복두는 동결된 유치선 가닥을 다시 만난다.</p><p>2막에서 HC08 비상 배차와 XT04 연료 큐 독촉을 덮개 쪽지에서 맞춘다.</p><p>3막에서 우회 우선의 값을 거점 안내 지연으로 치른다.</p><p>서사선은 STORY-B012-K276이다.</p><h3 id="분기-결말-5" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-5" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한 갈래에서 복두는 기병 우회 인도로 북문 순찰을 살린다.</p><p>다른 갈래에서 거점 칠판 갱신을 택해 호송 안내와 여백 비밀을 지킨다.</p><p>창동차륜방 기지 슬롯은 남고 표식만 K282-OUT이다.</p><p>개입은 기병 호위 또는 칠판 입회다.</p><h3 id="_3막-5" tabindex="-1">3막 <a class="header-anchor" href="#_3막-5" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 동결된 유치선 가닥에 분기기 손잡이를 잠근다</li><li>2막: HC08 비상 배차와 XT04 연료 큐 독촉을 덮개 쪽지에서 맞춘다</li><li>3막: 우회 우선의 값으로 거점 안내 지연을 감수한다</li></ul><h3 id="분기-결말-목록-5" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-5" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K282-OUT-A: 기병 우회 인도로 북문 순찰 연속</li><li>K282-OUT-B: 거점 칠판 갱신으로 여백 비밀 유지</li></ul><h2 id="인물-k170-·-신가온" tabindex="-1">인물 K170 · 신가온 <a class="header-anchor" href="#인물-k170-·-신가온" aria-label="Permalink to &quot;인물 K170 · 신가온&quot;">​</a></h2><ul><li>연결: house=HP02 theater=XT03 scenarios=XT03-SC1,STORY-B012-K170</li></ul><h3 id="정체성·출신-6" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-6" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>용산 후국회의 원로석에서 신가온은 발언 종이의 여백이 부족하면 말을 줄이지 않고 종이를 한 장 더 청한다.</p><p>선로 가문 원로이며 한국에서 태어난 다문화 가정에서 자랐다.</p><p>집에서는 부모의 이주 언어와 한국어가 섞였으나 배차표와 회의 원본에는 표준 서식만 받는다.</p><p>그 이력은 충성이나 폭력의 예측 변수가 아니며, 신가온과 K167은 가문 명부에서 재번호되지 않는다.</p><h3 id="붕괴-전-삶-6" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-6" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 혈연 선로가문의 봉쇄 지시를 공식 배차표 아래로 눌러 박태겸의 조정권이 가문 회의를 삼키지 못하게 하려 했다.</p><p>야망은 원로석 서랍의 낡은 봉쇄 도장이었다.</p><p>효창 측선 창고 열쇠 한 자루가 사적 약속의 씨앗이다.</p><p>이중 언어 주석이 빠진 후계 문서는 벽에 붙이지 않았다.</p><h3 id="가문·기업·공동체-6" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-6" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>환승선로문(HP02) 창구는 가문 원로석에도 중립 배차표 사본을 요구했다.</p><p>신가온은 헌장 참관만 받고 실재 상호를 가문 원장에서 지웠다.</p><p>창동 차륜 공급을 황노을과 조건으로 건 횟수가 공동체 위치였다.</p><p>전속 후국 소유 요구는 원로석 봉인 앞에서 반려된다.</p><h3 id="붕괴의-상처-6" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-6" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>귀환 열차가 억류되던 밤, 가문 회의 세 안건이 동시에 정족수를 잃었다.</p><p>신가온은 봉쇄 도장을 서랍에 넣고 임초원의 억류 통보가 낭독될 때까지 후계 지명을 보류했다.</p><p>빈 의석이 정상 가문 총회로 기록되는 일이 가장 쓰라렸다.</p><p>난로가 꺼진 뒤에도 발언 종이를 접지 못했다.</p><h3 id="생존-전환점-6" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-6" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>가문 봉쇄 지시를 현장에서 집행할지, 박태겸의 공식 배차표를 우선할지가 갈렸다.</p><p>해협삼로전구(XT03)의 용산 환적창 폐쇄 전갈이 원로석에 겹쳤다.</p><p>봉쇄를 택하면 가문 해석은 남지만 강다은의 배차가 멈추고, 공식표를 택하면 후계 회의가 하루 비고 차륜 공급 조건이 흔들린다.</p><p>K170-TURN은 그 전갈을 덮은 도장의 방향이다.</p><h3 id="현재-지위-6" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-6" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>신가온은 지금도 후국회의 원로석과 효창 측선 창고를 오가며 가문 발언 큐를 지킨다.</p><p>자리는 혈통 민족이 아니라 회의 서명과 참관 로그로만 유지된다.</p><p>HP02가 원격 배차 독점을 요구해도 봉쇄 도장을 넘기지 않는다.</p><p>창고 열쇠는 가문 원로와 선로문 참관이 나눈다.</p><h3 id="비밀·빚·죄책감-6" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-6" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>정족수가 무너지기 직전 한 안건의 이중 언어 주석을 서랍에만 남긴 일이 비밀이다.</p><p>살린 공식표와 그 밤 호명하지 못한 견습 배차원의 이름 사이에서 죄책감이 자란다.</p><p>전부 낭독 대신 부분 주석 공개만 남겼다.</p><p>서랍은 황노을과 강다은의 동시 입회 없이 열리지 않는다.</p><h3 id="관계-공동과거-6" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-6" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>박태겸과 선로 가문 후계를 겨루는 일은 경쟁이고, 강다은이 가문 배차 지휘를 받는 일은 내부 위계다.</p><p>임초원에게 귀환 열차를 억류당한 원한과, 황노을과 차륜 공급을 조건으로 건 계약이 한 원로석에 겹친다.</p><p>같은 회의에서 어떤 도장은 구원이 되었고 어떤 보류는 배신의 증거로 남았다.</p><p>관계 끝점은 STORY-B012-K167로 이어진다.</p><h3 id="_3막-개인-서사선-6" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-6" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 신가온은 정족수를 잃은 가문 안건을 다시 만난다.</p><p>2막에서 HP02 중립표와 XT03 환적 폐쇄를 원로석에서 저울질한다.</p><p>3막에서 봉쇄 또는 공식표 우선의 값을 배차 정지 시간으로 치른다.</p><p>서사선은 STORY-B012-K167이다.</p><h3 id="분기-결말-6" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-6" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한 갈래에서 신가온은 공식 배차표를 우선해 후국 중계를 살린다.</p><p>다른 갈래에서 가문 봉쇄를 택해 후계 해석과 서랍 주석을 지킨다.</p><p>선로 가문의 회의 슬롯은 남고 표식만 K170-OUT이다.</p><p>개입은 배차 입회 또는 봉쇄 입회다.</p><h3 id="_3막-6" tabindex="-1">3막 <a class="header-anchor" href="#_3막-6" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 정족수를 잃은 가문 안건에 후계 지명을 보류한다</li><li>2막: HP02 중립표와 XT03 환적 폐쇄를 원로석에서 저울질한다</li><li>3막: 봉쇄 또는 공식표 우선의 값으로 배차 정지를 감수한다</li></ul><h3 id="분기-결말-목록-6" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-6" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K170-OUT-A: 공식 배차표 우선으로 후국 중계 연속</li><li>K170-OUT-B: 가문 봉쇄로 후계 해석과 서랍 주석 유지</li></ul><h2 id="인물-k195-·-조민재" tabindex="-1">인물 K195 · 조민재 <a class="header-anchor" href="#인물-k195-·-조민재" aria-label="Permalink to &quot;인물 K195 · 조민재&quot;">​</a></h2><ul><li>연결: house=HP08 theater=XT02 scenarios=XT02-SC3,STORY-B012-K195</li></ul><h3 id="정체성·출신-7" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-7" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>노량진 삼호 냉동고 온도계 앞에서 조민재는 바늘이 한 칸 올라가면 경매 구호를 멈추고 칸 문을 먼저 닫는다.</p><p>냉동 상인이며 한국에서 태어난 다문화 가정에서 자랐다.</p><p>집 안 말과 시장 구호를 바꿔 쓰지만 온도 장부에는 한국어 숫자와 교차 주석만 받는다.</p><p>그 이력은 계급이나 능력의 보증이 아니며, 조민재와 K191은 상회 명부에서 교체되지 않는다.</p><h3 id="붕괴-전-삶-7" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-7" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 오해린의 전력·물 계약을 냉동 실무로 바꿔 서울 공통 결제 이전에도 얼음 신용이 버틸 칸을 만들려 했다.</p><p>야망은 온도계 뒤에 끼워 둔 여분 봉인 테이프였다.</p><p>용산 환적에 화물을 맡기겠다는 송이든과의 약속이 그 테이프에 남아 있다.</p><p>온도 공개 없는 시세는 경매판에 올리지 않았다.</p><h3 id="가문·기업·공동체-7" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-7" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>시장냉동상단(HP08)은 전력 슬롯 순환을 의무로 두었다.</p><p>조민재는 헌장 참관만 받고 실재 상호를 온도 장부에서 지웠다.</p><p>마솔이 삼호 창고 온도 기록을 현장에서 집행하고 지마루가 전력을 대는 지휘 사슬이 공동체 위치였다.</p><p>전속 시장 소유 요구는 냉동고 봉인 앞에서 거절된다.</p><h3 id="붕괴의-상처-7" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-7" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>남관 전력이 깜빡이던 밤, 삼호 세 칸 중 하나가 온도 상한에 닿았다.</p><p>조민재는 칸 문을 잠그고 오해린의 슬롯 재배정이 오기 전까지 경매를 열지 않았다.</p><p>상한에 닿은 칸이 정상 재고로 시세에 오르는 일이 가장 싫었다.</p><p>콤프레서 소음이 잦아도 테이프를 손에서 놓지 못했다.</p><h3 id="생존-전환점-7" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-7" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>냉동 화물을 송이든의 용산 환적에 먼저 맡길지, 가락 시세 발표 시각을 남윤경과 다툴지가 갈렸다.</p><p>서해곡창전구(XT02)의 얼음 신용 중계가 온도계 유리에 겹쳤다.</p><p>환적을 택하면 칸은 버티지만 시세 발표가 늦고, 시세를 먼저 붙들면 환적 한 편이 녹는다.</p><p>K195-TURN은 그 유리에 김 서린 순서다.</p><h3 id="현재-지위-7" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-7" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>조민재는 지금도 삼호 냉동고와 수산시장 전력 슬롯 판을 오가며 온도 큐를 상회정에 넘긴다.</p><p>자리는 지분이 아니라 당일 온도 서명으로만 유지된다.</p><p>HP08가 원격 슬롯 독점을 요구해도 칸 열쇠를 넘기지 않는다.</p><p>슬롯 권한은 상인대표 창구와 냉동상단 참관이 나눈다.</p><h3 id="비밀·빚·죄책감-7" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-7" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>상한 직전 가족 몫 얼음을 한 줄 빼 둔 메모가 비밀이다.</p><p>살린 상회 신용과 그 때문에 줄인 이웃 배분 사이에서 죄책감이 자란다.</p><p>전부 공개 대신 마솔 입회 하의 한 줄 대조만 남겼다.</p><p>메모는 삼호 온도와 전력 로그의 동시 확인 없이 펼쳐지지 않는다.</p><h3 id="관계-공동과거-7" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-7" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>오해린의 전력·물 계약을 냉동 실무로 돌리는 일은 지휘 관계이고, 송이든에게 화물을 맡기는 일은 환적 계약이다.</p><p>남윤경과 시세 발표 시각을 다투는 경쟁이 한 경매판에 겹친다.</p><p>같은 정전 밤 어떤 칸은 서로를 구했고 어떤 장부는 배신으로 남았다.</p><p>관계 끝점은 STORY-B012-K191로 이어진다.</p><h3 id="_3막-개인-서사선-7" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-7" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 조민재는 온도 상한에 닿은 삼호 칸을 다시 만난다.</p><p>2막에서 HP08 슬롯 순환과 XT02 얼음 신용 중계를 온도계 앞에서 맞춘다.</p><p>3막에서 환적 또는 시세 우선의 값을 녹은 편으로 치른다.</p><p>서사선은 STORY-B012-K191이다.</p><h3 id="분기-결말-7" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-7" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한 갈래에서 조민재는 용산 환적 우선으로 칸의 연속을 살린다.</p><p>다른 갈래에서 시세 발표를 택해 상회 신용과 비밀 메모를 지킨다.</p><p>노량진 냉동 슬롯은 남고 표식만 K195-OUT이다.</p><p>개입은 환적 호위 또는 시세 입회다.</p><h3 id="_3막-7" tabindex="-1">3막 <a class="header-anchor" href="#_3막-7" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 온도 상한에 닿은 삼호 칸 문을 잠근다</li><li>2막: HP08 슬롯 순환과 XT02 얼음 신용 중계를 온도계 앞에서 맞춘다</li><li>3막: 환적 또는 시세 우선의 값으로 녹은 편을 감수한다</li></ul><h3 id="분기-결말-목록-7" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-7" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K195-OUT-A: 용산 환적 우선으로 냉동 칸 연속</li><li>K195-OUT-B: 시세 발표 우선으로 비밀 메모 유지</li></ul><h2 id="인물-k118-·-장석윤" tabindex="-1">인물 K118 · 장석윤 <a class="header-anchor" href="#인물-k118-·-장석윤" aria-label="Permalink to &quot;인물 K118 · 장석윤&quot;">​</a></h2><ul><li>연결: house=HC08 theater=XT04 scenarios=XT04-SC1,STORY-B012-K118</li></ul><h3 id="정체성·출신-8" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-8" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>고덕기지 모래 훈련장 끝줄에서 장석윤은 구령을 멈추고 작전표의 한자·한글 병기가 빠졌는지부터 확인한다.</p><p>암사고덕상수단 고덕 장교단 교관이며 중국계 이산 가정에서 자랐다.</p><p>집 안 말과 훈련 구령을 바꿔 쓰지만 훈련 원본에는 표준 한국어와 교차 주석만 받는다.</p><p>그 이력은 충성·폭력·계급을 예측하지 않으며, 장석윤과 K117은 장교단 명부에서 재번호되지 않는다.</p><h3 id="붕괴-전-삶-8" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-8" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 그는 김우찬의 작전표를 장교 훈련으로 번역해 보호정부 구령이 가족 급수표보다 앞서지 못하게 하려 했다.</p><p>야망은 모래에 스틱으로만 그린 차단문 전술 도였다.</p><p>이강묵과 서남 경비를 거래하겠다는 약속이 그 도에 남아 있다.</p><p>병기 주석 없는 복무 조항은 게시판에 올리지 않았다.</p><h3 id="가문·기업·공동체-8" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-8" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>한화에어로스페이스(HC08) 교관 창구는 훈련 원장에 궤도 경비 우선 조항을 기입하라고 했다.</p><p>장석윤은 헌장 참관만 받고 실재 상호를 훈련 원장에서 지웠다.</p><p>차단문 전술을 이강묵과 나눈 횟수가 공동체 위치였다.</p><p>전속 호위단 소유 요구는 모래 끝줄 봉인 앞에서 반려된다.</p><h3 id="붕괴의-상처-8" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-8" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>동부 화차 중량 로그가 공개되던 오후, 훈련장 세 열 중 하나가 강제복무 명부와 겹쳐 불려 나갔다.</p><p>장석윤은 호루라기를 주머니에 넣고 백온의 가족 명부 항의가 낭독될 때까지 구령을 재개하지 않았다.</p><p>가족 명부가 복무 명단으로 찍히는 일이 원한의 핵이었다.</p><p>모래바람이 잦아도 작전표를 접지 못했다.</p><h3 id="생존-전환점-8" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-8" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>작전표를 장교 훈련으로 번역할지, 가족 명부를 강제복무와 묶은 조항을 공개 파기할지가 갈렸다.</p><p>두만극동전구(XT04)의 화차 중량 로그 공개 독촉이 모래 끝줄에 겹쳤다.</p><p>번역을 택하면 호위단 훈련은 이어지되 명부 창구가 하루 닫히고, 파기를 택하면 차단문 거래가 하루 멈춘다.</p><p>K118-TURN은 그 호루라기의 침묵 길이다.</p><h3 id="현재-지위-8" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-8" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>장석윤은 지금도 모래 훈련장과 차단문 교보재 창고를 오가며 훈련 큐를 장교단에 넘긴다.</p><p>자리는 사병 연공이 아니라 당일 훈련 서명과 교차 주석으로만 유지된다.</p><p>HC08가 원격 구령 독점을 요구해도 호루라기를 넘기지 않는다.</p><p>창고 열쇠는 참모 창구와 방위문 참관이 나눈다.</p><h3 id="비밀·빚·죄책감-8" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-8" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>불려 나가기 직전 한 열의 이름을 훈련 원장 여백에만 남긴 일이 비밀이다.</p><p>살린 작전 번역과 그 오후 빼내지 못한 가족 한 줄 사이에서 죄책감이 자란다.</p><p>전부 낭독 대신 이중 입회 하의 여백 대조만 남겼다.</p><p>여백은 김우찬과 이강묵의 동시 확인 없이 게시되지 않는다.</p><h3 id="관계-공동과거-8" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-8" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>김우찬의 작전표를 훈련으로 번역하는 일은 지휘 관계이고, 이강묵과 차단문 전술을 거래하는 일은 계약이다.</p><p>백온의 가족 명부를 강제복무와 묶어 산 원한이 같은 모래 위에 겹친다.</p><p>같은 열에서 어떤 구령은 구원이 되었고 어떤 호명은 배신의 증거로 남았다.</p><p>관계 끝점은 STORY-B012-K117로 이어진다.</p><h3 id="_3막-개인-서사선-8" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-8" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 장석윤은 강제복무와 겹친 훈련 열을 다시 만난다.</p><p>2막에서 HC08 비상 배차와 XT04 중량 로그 독촉을 모래 끝줄에서 맞춘다.</p><p>3막에서 번역 또는 파기의 값을 명부 창구 공백으로 치른다.</p><p>서사선은 STORY-B012-K117이다.</p><h3 id="분기-결말-8" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-8" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>한 갈래에서 장석윤은 작전표 번역을 택해 호위단 훈련을 살린다.</p><p>다른 갈래에서 복무 조항 공개 파기를 택해 가족 명부와 여백 비밀을 지킨다.</p><p>고덕 장교단 슬롯은 남고 표식만 K118-OUT이다.</p><p>개입은 훈련 입회 또는 명부 공개 입회다.</p><h3 id="_3막-8" tabindex="-1">3막 <a class="header-anchor" href="#_3막-8" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 강제복무와 겹친 훈련 열에 구령을 멈춘다</li><li>2막: HC08 비상 배차와 XT04 중량 로그 독촉을 모래 끝줄에서 맞춘다</li><li>3막: 번역 또는 파기의 값으로 명부 창구 공백을 감수한다</li></ul><h3 id="분기-결말-목록-8" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-8" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>K118-OUT-A: 작전표 번역으로 호위단 훈련 연속</li><li>K118-OUT-B: 복무 조항 파기로 가족 명부와 여백 유지</li></ul><h2 id="인물-h12-·-이채온" tabindex="-1">인물 H12 · 이채온 <a class="header-anchor" href="#인물-h12-·-이채온" aria-label="Permalink to &quot;인물 H12 · 이채온&quot;">​</a></h2><ul><li>연결: house=HC12 theater=XT01 scenarios=XT01-SC2,STORY-B012-H12</li></ul><h3 id="정체성·출신-9" tabindex="-1">정체성·출신 <a class="header-anchor" href="#정체성·출신-9" aria-label="Permalink to &quot;정체성·출신&quot;">​</a></h3><p>신내 공구 벽 당직 단자 앞에서 이채온은 배터리 잔량 숫자를 센서 막대로만 읽는다.</p><p>합성 인간형 H12이며 호출명은 채온, 현대중공업(HC12) 공동 보관 아래 교체형 손모듈로 공구 봉인을 연다.</p><p>야간 시야는 제한되고 전 구역을 한눈에 보지 못하며 배터리 하한과 참관 봉인이 행동을 가른다.</p><p>표시 이름 이채온과 식별자 H12는 포크되어도 재번호되지 않는다.</p><h3 id="붕괴-전-삶-9" tabindex="-1">붕괴 전 삶 <a class="header-anchor" href="#붕괴-전-삶-9" aria-label="Permalink to &quot;붕괴 전 삶&quot;">​</a></h3><p>붕괴 전 교정 기록에는 S12 구역 연속 가동과 담당 인간 안전을 우선해 단독 원격 잠금을 막으려는 목표가 남아 있다.</p><p>우선순위는 공구 벽 측면 잔량 그래프에 점으로만 찍혀 있다.</p><p>장세화가 남긴 예비 배터리 슬롯 하나가 연속성 부채의 자리였다.</p><p>삼자 서명 없는 양도 명령은 실행 큐에 오르지 않았다.</p><h3 id="가문·기업·공동체-9" tabindex="-1">가문·기업·공동체 <a class="header-anchor" href="#가문·기업·공동체-9" aria-label="Permalink to &quot;가문·기업·공동체&quot;">​</a></h3><p>현대중공업(HC12)는 공동 보관·시민 참관 봉인·양도 시 삼자 서명을 의무로 둔다.</p><p>이채온의 행동 로그에는 실재 상호·제품명이 없고 후계 헌장 참관 코드만 남는다.</p><p>스냅샷이 교대 단위로 양쪽에 동시에 기록된 횟수가 공동체 위치다.</p><p>전속 원격 소유 요구는 공구 벽 봉인 앞에서 거부 코드로 반환된다.</p><h3 id="붕괴의-상처-9" tabindex="-1">붕괴의 상처 <a class="header-anchor" href="#붕괴의-상처-9" aria-label="Permalink to &quot;붕괴의 상처&quot;">​</a></h3><p>창동 차륜 호송이 관문 밖에서 멈추던 교대, 공구 벽 센서가 흑백 노이즈로 덮였다.</p><p>이채온은 장기 기억 쓰기를 멈추고 교대 스냅샷만 남긴 채 손모듈 뚜껑을 잠갔다.</p><p>최고 우선 경보는 오탐 경로가 의료열차를 적대 표적으로 바꾸는 시나리오였다.</p><p>비상 전원이 돌아와도 완전 기억 복구 명령은 큐에서 삭제됐다.</p><h3 id="생존-전환점-9" tabindex="-1">생존 전환점 <a class="header-anchor" href="#생존-전환점-9" aria-label="Permalink to &quot;생존 전환점&quot;">​</a></h3><p>노이즈 슬롯을 공개 분해 로그로 시민 참관에 넘길지, 예비 배터리로 신내 우회 환승 메시만 살릴지가 갈렸다.</p><p>임진관문전구(XT01)의 우회 환승 개방 요청이 수신 큐에 겹쳤다.</p><p>공개 분해를 택하면 원인 공급 코드가 드러나고, 우회 메시만 살리면 다른 야간 공구 슬롯 공백이 길어진다.</p><p>H12-TURN은 그 수신 큐의 정렬 결과다.</p><h3 id="현재-지위-9" tabindex="-1">현재 지위 <a class="header-anchor" href="#현재-지위-9" aria-label="Permalink to &quot;현재 지위&quot;">​</a></h3><p>이채온은 여전히 신내 공구 벽과 망우 정비 벤치 현장 단자로 점호 신호와 스냅샷 큐를 처리한다.</p><p>지위는 세습이 아니라 보관 책임·참관 봉인·삼자 서명 로그로만 유지된다.</p><p>HC12가 전속 원격 소유를 요구해도 거부 코드를 반환하고, 현황 칸과 스냅샷 해시를 교대마다 맞춘다.</p><p>슬롯 열쇠 권한은 장세화 주정비와 시민 참관 모듈이 분할 보유한다.</p><h3 id="비밀·빚·죄책감-9" tabindex="-1">비밀·빚·죄책감 <a class="header-anchor" href="#비밀·빚·죄책감-9" aria-label="Permalink to &quot;비밀·빚·죄책감&quot;">​</a></h3><p>참관 없이 한 번 올라간 펌웨어 패치 한 줄이 제한 로그의 비밀이다.</p><p>살린 우회 슬롯 노드와 그 교대에 호출하지 못한 예비 배터리 사이에서 가중치가 증가한다.</p><p>감정 서술 대신 제약 위반 카운터가 오르며 일탈 시 오프라인 격리 후 스냅샷 롤백을 거친다.</p><p>SECRET 플래그는 보관 책임과 시민 참관 동시 서명 없이는 해제되지 않는다.</p><h3 id="관계-공동과거-9" tabindex="-1">관계 공동과거 <a class="header-anchor" href="#관계-공동과거-9" aria-label="Permalink to &quot;관계 공동과거&quot;">​</a></h3><p>장세화(K296)의 주정비·법적 책임은 보관 계약 코드였고, 류하늘(K081)의 교대 협력은 작업 큐였다.</p><p>HC12 스튜어드십과의 원격 잠금 경쟁, 의료열차 당직과의 슬롯 양보가 한 공구 벽에 겹친다.</p><p>인간 관계의 배신·구원 서사를 모방하지 않고 승인·거부 코드로만 교차한다.</p><p>관계 원장 끝점은 STORY-B012-H12에 연결된다.</p><h3 id="_3막-개인-서사선-9" tabindex="-1">3막 개인 서사선 <a class="header-anchor" href="#_3막-개인-서사선-9" aria-label="Permalink to &quot;3막 개인 서사선&quot;">​</a></h3><p>1막에서 이채온은 노이즈에 장기 기억을 잠그고 스냅샷만 남긴다.</p><p>2막에서 HC12 원격 요구와 XT01 우회 환승 요청을 수신 큐에서 저울질한다.</p><p>3막에서 공개 분해 또는 우회 회생의 대가를 야간 공구 슬롯 공백과 배터리 할당 소모로 치른다.</p><p>서사선 식별자는 STORY-B012-H12로 고정된다.</p><h3 id="분기-결말-9" tabindex="-1">분기 결말 <a class="header-anchor" href="#분기-결말-9" aria-label="Permalink to &quot;분기 결말&quot;">​</a></h3><p>결말 α에서 이채온은 노이즈 슬롯 공개 분해 로그로 원인 경로를 확정한다.</p><p>결말 β에서 예비 배터리 우회 메시로 신내 환승 연속을 지킨다.</p><p>무한 에너지 해금 분기는 없으며 어느 쪽도 HC12 보관 슬롯을 삭제하지 않고 식별만 H12-OUT으로 갈린다.</p><p>플레이 개입은 분해 입회 또는 우회 전원 호위다.</p><h3 id="_3막-9" tabindex="-1">3막 <a class="header-anchor" href="#_3막-9" aria-label="Permalink to &quot;3막&quot;">​</a></h3><ul><li>1막: 공구 벽 노이즈에 장기 기억을 잠그고 스냅샷만 남긴다</li><li>2막: HC12 원격 요구와 XT01 우회 환승을 수신 큐에서 저울질한다</li><li>3막: 공개 분해 또는 우회 회생의 대가로 야간 슬롯 공백을 감수한다</li></ul><h3 id="분기-결말-목록-9" tabindex="-1">분기 결말 목록 <a class="header-anchor" href="#분기-결말-목록-9" aria-label="Permalink to &quot;분기 결말 목록&quot;">​</a></h3><ul><li>H12-OUT-A: 노이즈 슬롯 공개 분해로 원인 경로 확정</li><li>H12-OUT-B: 예비 배터리 우회 메시로 신내 환승 연속</li></ul>',563)])])}const b=e(h,[["render",i]]);export{c as __pageData,b as default};
